import { LangSmithLoader } from "../langsmith.js";

const DATASET_NAME = "brace-test-dataset";
const DATASET_ID = "9a3b36f7-a297-40a5-944d-6613853b6330";

test("LangSmithLoader can load with client passed in", async () => {
  const lsClient = new Client();
  const loader = new LangSmithLoader({
    datasetId: DATASET_ID,
    client: lsClient,
  });
  const docs = await loader.load();

  expect(docs.length).toBeGreaterThanOrEqual(1);
  console.log(docs[0]);
  const parsedContent = JSON.parse(docs[0].pageContent);
  expect(parsedContent).toHaveProperty("input_key_str");
  expect(parsedContent.input_key_str).toBe("string");
  expect(parsedContent).toHaveProperty("input_key_bool");
  expect(parsedContent.input_key_bool).toBe(true);

  expect(docs[0].metadata).toHaveProperty("created_at");
  expect(typeof docs[0].metadata.created_at).toBe("string");
  expect(docs[0].metadata).toHaveProperty("modified_at");
  expect(typeof docs[0].metadata.modified_at).toBe("string");
});

test("LangSmithLoader can load with client options passed in", async () => {
  const lsApiKey = process.env.LANGCHAIN_API_KEY;
  // unassign the API key to confirm the client isn't overriding what we passed in.
  process.env.LANGCHAIN_API_KEY = "";

  try {
    const lsConfigArgs = {
      apiKey: lsApiKey,
    };
    const loader = new LangSmithLoader({
      datasetId: DATASET_ID,
      clientConfig: lsConfigArgs,
    });
    const docs = await loader.load();

    expect(docs.length).toBeGreaterThanOrEqual(1);
  } finally {
    process.env.LANGCHAIN_API_KEY = lsApiKey;
  }
});

test("LangSmithLoader can load with dataset name", async () => {
  const loader = new LangSmithLoader({ datasetName: DATASET_NAME });
  const docs = await loader.load();

  expect(docs.length).toBeGreaterThanOrEqual(1);
});

test("Passing content key correctly loads that value", async () => {
  const loader = new LangSmithLoader({
    datasetName: DATASET_NAME,
    contentKey: "input_key_str",
  });
  const docs = await loader.load();

  expect(docs[0].pageContent).toBe("string");
});

from typing import List, Optional

import requests
from langchain_core.documents import Document

from langchain_community.document_loaders.base import BaseLoader
from langchain_community.document_loaders.web_base import WebBaseLoader

IFIXIT_BASE_URL = "https://www.ifixit.com/api/2.0"


class IFixitLoader(BaseLoader):
    """Load `iFixit` repair guides, device wikis and answers.

    iFixit is the largest, open repair community on the web. The site contains nearly
    100k repair manuals, 200k Questions & Answers on 42k devices, and all the data is
    licensed under CC-BY.

    This loader will allow you to download the text of a repair guide, text of Q&A's
    and wikis from devices on iFixit using their open APIs and web scraping.
    """

    def __init__(self, web_path: str):
        """Initialize with a web path."""
        if not web_path.startswith("https://www.ifixit.com"):
            raise ValueError("web path must start with 'https://www.ifixit.com'")

        path = web_path.replace("https://www.ifixit.com", "")

        allowed_paths = ["/Device", "/Guide", "/Answers", "/Teardown"]

        """ TODO: Add /Wiki """
        if not any(path.startswith(allowed_path) for allowed_path in allowed_paths):
            raise ValueError(
                "web path must start with /Device, /Guide, /Teardown or /Answers"
            )

        pieces = [x for x in path.split("/") if x]

        """Teardowns are just guides by a different name"""
        self.page_type = pieces[0] if pieces[0] != "Teardown" else "Guide"

        if self.page_type == "Guide" or self.page_type == "Answers":
            self.id = pieces[2]
        else:
            self.id = pieces[1]

        self.web_path = web_path

    def load(self) -> List[Document]:
        if self.page_type == "Device":
            return self.load_device()
        elif self.page_type == "Guide" or self.page_type == "Teardown":
            return self.load_guide()
        elif self.page_type == "Answers":
            return self.load_questions_and_answers()
        else:
            raise ValueError("Unknown page type: " + self.page_type)

    @staticmethod
    def load_suggestions(query: str = "", doc_type: str = "all") -> List[Document]:
        """Load suggestions.

        Args:
            query: A query string
            doc_type: The type of document to search for. Can be one of "all",
              "device", "guide", "teardown", "answer", "wiki".

        Returns:

        """
        res = requests.get(
            IFIXIT_BASE_URL + "/suggest/" + query + "?doctypes=" + doc_type
        )

        if res.status_code != 200:
            raise ValueError(
                'Could not load suggestions for "' + query + '"\n' + res.json()
            )

        data = res.json()

        results = data["results"]
        output = []

        for result in results:
            try:
                loader = IFixitLoader(result["url"])
                if loader.page_type == "Device":
                    output += loader.load_device(include_guides=False)
                else:
                    output += loader.load()
            except ValueError:
                continue

        return output

    def load_questions_and_answers(
        self, url_override: Optional[str] = None
    ) -> List[Document]:
        """Load a list of questions and answers.

        Args:
            url_override: A URL to override the default URL.

        Returns: List[Document]

        """
        loader = WebBaseLoader(self.web_path if url_override is None else url_override)
        soup = loader.scrape()

        output = []

        title = soup.find("h1", "post-title").text

        output.append("# " + title)
        output.append(soup.select_one(".post-content .post-text").text.strip())

        answersHeader = soup.find("div", "post-answers-header")
        if answersHeader:
            output.append("\n## " + answersHeader.text.strip())

        for answer in soup.select(".js-answers-list .post.post-answer"):
            if answer.has_attr("itemprop") and "acceptedAnswer" in answer["itemprop"]:
                output.append("\n### Accepted Answer")
            elif "post-helpful" in answer["class"]:
                output.append("\n### Most Helpful Answer")
            else:
                output.append("\n### Other Answer")

            output += [
                a.text.strip() for a in answer.select(".post-content .post-text")
            ]
            output.append("\n")

        text = "\n".join(output).strip()

        metadata = {"source": self.web_path, "title": title}

        return [Document(page_content=text, metadata=metadata)]

    def load_device(
        self, url_override: Optional[str] = None, include_guides: bool = True
    ) -> List[Document]:
        """Loads a device

        Args:
            url_override: A URL to override the default URL.
            include_guides: Whether to include guides linked to from the device.
              Defaults to True.

        Returns:

        """
        documents = []
        if url_override is None:
            url = IFIXIT_BASE_URL + "/wikis/CATEGORY/" + self.id
        else:
            url = url_override

        res = requests.get(url)
        data = res.json()
        text = "\n".join(
            [
                data[key]
                for key in ["title", "description", "contents_raw"]
                if key in data
            ]
        ).strip()

        metadata = {"source": self.web_path, "title": data["title"]}
        documents.append(Document(page_content=text, metadata=metadata))

        if include_guides:
            """Load and return documents for each guide linked to from the device"""
            guide_urls = [guide["url"] for guide in data["guides"]]
            for guide_url in guide_urls:
                documents.append(IFixitLoader(guide_url).load()[0])

        return documents

    def load_guide(self, url_override: Optional[str] = None) -> List[Document]:
        """Load a guide

        Args:
            url_override: A URL to override the default URL.

        Returns: List[Document]

        """
        if url_override is None:
            url = IFIXIT_BASE_URL + "/guides/" + self.id
        else:
            url = url_override

        res = requests.get(url)

        if res.status_code != 200:
            raise ValueError(
                "Could not load guide: " + self.web_path + "\n" + res.json()
            )

        data = res.json()

        doc_parts = ["# " + data["title"], data["introduction_raw"]]

        doc_parts.append("\n\n###Tools Required:")
        if len(data["tools"]) == 0:
            doc_parts.append("\n - None")
        else:
            for tool in data["tools"]:
                doc_parts.append("\n - " + tool["text"])

        doc_parts.append("\n\n###Parts Required:")
        if len(data["parts"]) == 0:
            doc_parts.append("\n - None")
        else:
            for part in data["parts"]:
                doc_parts.append("\n - " + part["text"])

        for row in data["steps"]:
            doc_parts.append(
                "\n\n## "
                + (
                    row["title"]
                    if row["title"] != ""
                    else "Step {}".format(row["orderby"])
                )
            )

            for line in row["lines"]:
                doc_parts.append(line["text_raw"])

        doc_parts.append(data["conclusion_raw"])

        text = "\n".join(doc_parts)

        metadata = {"source": self.web_path, "title": data["title"]}

        return [Document(page_content=text, metadata=metadata)]

import type { basename as BasenameT } from "node:path";
import type { readFile as ReadFileT, stat as StatT } from "node:fs/promises";
import yaml from "js-yaml";
import { Document } from "@langchain/core/documents";
import { getEnv } from "@langchain/core/utils/env";
import { BaseDocumentLoader } from "@langchain/core/document_loaders/base";
import {
  DirectoryLoader,
  UnknownHandling,
} from "langchain/document_loaders/fs/directory";

export type FrontMatter = {
  title?: string;
  description?: string;
  tags?: string[] | string;
  [key: string]: unknown;
};

export interface ObsidianFileLoaderOptions {
  encoding?: BufferEncoding;
  collectMetadata?: boolean;
}

/**
 * Represents a loader for Obsidian markdown files. This loader extends the BaseDocumentLoader
 * and provides functionality to parse and extract metadata, tags, and dataview fields from
 * Obsidian markdown files.
 */
class ObsidianFileLoader extends BaseDocumentLoader {
  private filePath: string;

  private encoding: BufferEncoding;

  private collectMetadata: boolean;

  /**
   * Initializes a new instance of the ObsidianFileLoader class.
   * @param filePath The path to the Obsidian markdown file.
   * @param encoding The character encoding to use when reading the file. Defaults to 'utf-8'.
   * @param collectMetadata Determines whether metadata should be collected from the file. Defaults to true.
   */
  constructor(
    filePath: string,
    {
      encoding = "utf-8",
      collectMetadata = true,
    }: ObsidianFileLoaderOptions = {}
  ) {
    super();
    this.filePath = filePath;
    this.encoding = encoding;
    this.collectMetadata = collectMetadata;
  }

  private static FRONT_MATTER_REGEX = /^---\n(.*?)\n---\n/s;

  /**
   * Parses the YAML front matter from the given content string.
   * @param content The string content of the markdown file.
   * @returns An object representing the parsed front matter.
   */
  private parseFrontMatter(content: string): FrontMatter {
    if (!this.collectMetadata) {
      return {};
    }

    const match = content.match(ObsidianFileLoader.FRONT_MATTER_REGEX);
    if (!match) {
      return {};
    }

    try {
      const frontMatter = yaml.load(match[1]) as FrontMatter;
      if (frontMatter.tags && typeof frontMatter.tags === "string") {
        frontMatter.tags = frontMatter.tags.split(", ");
      }

      return frontMatter;
    } catch (e) {
      console.warn("Encountered non-yaml frontmatter");
      return {};
    }
  }

  /**
   * Removes YAML front matter from the given content string.
   * @param content The string content of the markdown file.
   * @returns The content string with the front matter removed.
   */
  private removeFrontMatter(content: string): string {
    if (!this.collectMetadata) {
      return content;
    }

    return content.replace(ObsidianFileLoader.FRONT_MATTER_REGEX, "");
  }

  private static TAG_REGEX = /(?:\s|^)#([a-zA-Z_][\w/-]*)/g;

  /**
   * Parses Obsidian-style tags from the given content string.
   * @param content The string content of the markdown file.
   * @returns A set of parsed tags.
   */
  private parseObsidianTags(content: string): Set<string> {
    if (!this.collectMetadata) {
      return new Set();
    }

    const matches = content.matchAll(ObsidianFileLoader.TAG_REGEX);
    const tags = new Set<string>();
    for (const match of matches) {
      tags.add(match[1]);
    }

    return tags;
  }

  private static DATAVIEW_LINE_REGEX = /^\s*(\w+)::\s*(.*)$/gm;

  private static DATAVIEW_INLINE_BRACKET_REGEX = /\[(\w+)::\s*(.*)\]/gm;

  private static DATAVIEW_INLINE_PAREN_REGEX = /\((\w+)::\s*(.*)\)/gm;

  /**
   * Parses dataview fields from the given content string.
   * @param content The string content of the markdown file.
   * @returns A record object containing key-value pairs of dataview fields.
   */
  private parseObsidianDataviewFields(content: string): Record<string, string> {
    if (!this.collectMetadata) {
      return {};
    }

    const fields: Record<string, string> = {};
    const lineMatches = content.matchAll(
      ObsidianFileLoader.DATAVIEW_LINE_REGEX
    );
    for (const [, key, value] of lineMatches) {
      fields[key] = value;
    }

    const bracketMatches = content.matchAll(
      ObsidianFileLoader.DATAVIEW_INLINE_BRACKET_REGEX
    );
    for (const [, key, value] of bracketMatches) {
      fields[key] = value;
    }

    const parenMatches = content.matchAll(
      ObsidianFileLoader.DATAVIEW_INLINE_PAREN_REGEX
    );
    for (const [, key, value] of parenMatches) {
      fields[key] = value;
    }

    return fields;
  }

  /**
   * Converts metadata to a format compatible with Langchain.
   * @param metadata The metadata object to convert.
   * @returns A record object containing key-value pairs of Langchain-compatible metadata.
   */
  private toLangchainCompatibleMetadata(metadata: Record<string, unknown>) {
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(metadata)) {
      if (typeof value === "string" || typeof value === "number") {
        result[key] = value;
      } else {
        result[key] = JSON.stringify(value);
      }
    }
    return result;
  }

  /**
   * It loads the Obsidian file, parses it, and returns a `Document` instance.
   * @returns An array of `Document` instances to comply with the BaseDocumentLoader interface.
   */
  public async load(): Promise<Document[]> {
    const documents: Document[] = [];

    const { basename, readFile, stat } = await ObsidianFileLoader.imports();
    const fileName = basename(this.filePath);
    const stats = await stat(this.filePath);
    let content = await readFile(this.filePath, this.encoding);

    const frontMatter = this.parseFrontMatter(content);
    const tags = this.parseObsidianTags(content);
    const dataviewFields = this.parseObsidianDataviewFields(content);
    content = this.removeFrontMatter(content);

    const metadata: Document["metadata"] = {
      source: fileName,
      path: this.filePath,
      created: stats.birthtimeMs,
      lastModified: stats.mtimeMs,
      lastAccessed: stats.atimeMs,
      ...this.toLangchainCompatibleMetadata(frontMatter),
      ...dataviewFields,
    };

    if (tags.size || frontMatter.tags) {
      metadata.tags = Array.from(
        new Set([...tags, ...(frontMatter.tags ?? [])])
      ).join(",");
    }

    documents.push(
      new Document({
        pageContent: content,
        metadata,
      })
    );

    return documents;
  }

  /**
   * Imports the necessary functions from the `node:path` and
   * `node:fs/promises` modules. It is used to dynamically import the
   * functions when needed. If the import fails, it throws an error
   * indicating that the modules failed to load.
   * @returns A promise that resolves to an object containing the imported functions.
   */
  static async imports(): Promise<{
    basename: typeof BasenameT;
    readFile: typeof ReadFileT;
    stat: typeof StatT;
  }> {
    try {
      const { basename } = await import("node:path");
      const { readFile, stat } = await import("node:fs/promises");
      return { basename, readFile, stat };
    } catch (e) {
      console.error(e);
      throw new Error(
        `Failed to load fs/promises. ObsidianFileLoader available only on environment 'node'. It appears you are running environment '${getEnv()}'. See https://<link to docs> for alternatives.`
      );
    }
  }
}

/**
 * Represents a loader for directories containing Obsidian markdown files. This loader extends
 * the DirectoryLoader and provides functionality to load and parse '.md' files with YAML frontmatter,
 * Obsidian tags, and Dataview fields.
 */
export class ObsidianLoader extends DirectoryLoader {
  /**
   * Initializes a new instance of the ObsidianLoader class.
   * @param directoryPath The path to the directory containing Obsidian markdown files.
   * @param encoding The character encoding to use when reading files. Defaults to 'utf-8'.
   * @param collectMetadata Determines whether metadata should be collected from the files. Defaults to true.
   */
  constructor(directoryPath: string, options?: ObsidianFileLoaderOptions) {
    super(
      directoryPath,
      {
        ".md": (filePath) => new ObsidianFileLoader(filePath, options),
      },
      true,
      UnknownHandling.Ignore
    );
  }
}

class CollectionCommon(Generic[ClientT]):
    _model: CollectionModel
    _client: ClientT
    _embedding_function: Optional[EmbeddingFunction[Embeddable]]
    _data_loader: Optional[DataLoader[Loadable]]

    def __init__(
        self,
        client: ClientT,
        model: CollectionModel,
        embedding_function: Optional[
            EmbeddingFunction[Embeddable]
        ] = ef.DefaultEmbeddingFunction(),  # type: ignore
        data_loader: Optional[DataLoader[Loadable]] = None,
    ):
        """Initializes a new instance of the Collection class."""

        self._client = client
        self._model = model

        # Check to make sure the embedding function has the right signature, as defined by the EmbeddingFunction protocol
        if embedding_function is not None:
            validate_embedding_function(embedding_function)

        self._embedding_function = embedding_function
        self._data_loader = data_loader

    # Expose the model properties as read-only properties on the Collection class

    @property
    def id(self) -> UUID:
        return self._model.id

    @property
    def name(self) -> str:
        return self._model.name

    @property
    def configuration_json(self) -> Dict[str, Any]:
        return self._model.configuration_json

    @property
    def metadata(self) -> CollectionMetadata:
        return cast(CollectionMetadata, self._model.metadata)

    @property
    def tenant(self) -> str:
        return self._model.tenant

    @property
    def database(self) -> str:
        return self._model.database

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, CollectionCommon):
            return False
        id_match = self.id == other.id
        name_match = self.name == other.name
        configuration_match = self.configuration_json == other.configuration_json
        metadata_match = self.metadata == other.metadata
        tenant_match = self.tenant == other.tenant
        database_match = self.database == other.database
        embedding_function_match = self._embedding_function == other._embedding_function
        data_loader_match = self._data_loader == other._data_loader
        return (
            id_match
            and name_match
            and configuration_match
            and metadata_match
            and tenant_match
            and database_match
            and embedding_function_match
            and data_loader_match
        )

    def __repr__(self) -> str:
        return f"Collection(id={self.id}, name={self.name})"

    def get_model(self) -> CollectionModel:
        return self._model

    def _validate_embedding_set(
        self,
        ids: OneOrMany[ID],
        embeddings: Optional[
            Union[
                OneOrMany[Embedding],
                OneOrMany[PyEmbedding],
            ]
        ],
        metadatas: Optional[OneOrMany[Metadata]],
        documents: Optional[OneOrMany[Document]],
        images: Optional[OneOrMany[Image]] = None,
        uris: Optional[OneOrMany[URI]] = None,
        require_embeddings_or_data: bool = True,
    ) -> Tuple[
        IDs,
        Optional[Embeddings],
        Optional[Metadatas],
        Optional[Documents],
        Optional[Images],
        Optional[URIs],
    ]:
        valid_ids = validate_ids(maybe_cast_one_to_many_ids(ids))
        valid_embeddings = (
            validate_embeddings(
                self._normalize_embeddings(maybe_cast_one_to_many_embedding(embeddings))
            )
            if embeddings is not None
            else None
        )
        valid_metadatas = (
            validate_metadatas(maybe_cast_one_to_many_metadata(metadatas))
            if metadatas is not None
            else None
        )
        valid_documents = (
            maybe_cast_one_to_many_document(documents)
            if documents is not None
            else None
        )
        valid_images = (
            maybe_cast_one_to_many_image(images) if images is not None else None
        )

        valid_uris = maybe_cast_one_to_many_uri(uris) if uris is not None else None

        # Check that one of embeddings or ducuments or images is provided
        if require_embeddings_or_data:
            if (
                valid_embeddings is None
                and valid_documents is None
                and valid_images is None
                and valid_uris is None
            ):
                raise ValueError(
                    "You must provide embeddings, documents, images, or uris."
                )

        # Only one of documents or images can be provided
        if valid_documents is not None and valid_images is not None:
            raise ValueError("You can only provide documents or images, not both.")

        # Check that, if they're provided, the lengths of the arrays match the length of ids
        if valid_embeddings is not None and len(valid_embeddings) != len(valid_ids):
            raise ValueError(
                f"Number of embeddings {len(valid_embeddings)} must match number of ids {len(valid_ids)}"
            )
        if valid_metadatas is not None and len(valid_metadatas) != len(valid_ids):
            raise ValueError(
                f"Number of metadatas {len(valid_metadatas)} must match number of ids {len(valid_ids)}"
            )
        if valid_documents is not None and len(valid_documents) != len(valid_ids):
            raise ValueError(
                f"Number of documents {len(valid_documents)} must match number of ids {len(valid_ids)}"
            )
        if valid_images is not None and len(valid_images) != len(valid_ids):
            raise ValueError(
                f"Number of images {len(valid_images)} must match number of ids {len(valid_ids)}"
            )
        if valid_uris is not None and len(valid_uris) != len(valid_ids):
            raise ValueError(
                f"Number of uris {len(valid_uris)} must match number of ids {len(valid_ids)}"
            )

        return (
            valid_ids,
            valid_embeddings,
            valid_metadatas,
            valid_documents,
            valid_images,
            valid_uris,
        )

    def _validate_and_prepare_embedding_set(
        self,
        ids: OneOrMany[ID],
        embeddings: Optional[
            Union[
                OneOrMany[Embedding],
                OneOrMany[PyEmbedding],
            ]
        ],
        metadatas: Optional[OneOrMany[Metadata]],
        documents: Optional[OneOrMany[Document]],
        images: Optional[OneOrMany[Image]],
        uris: Optional[OneOrMany[URI]],
    ) -> Tuple[
        IDs,
        Embeddings,
        Optional[Metadatas],
        Optional[Documents],
        Optional[URIs],
    ]:
        (
            ids,
            embeddings,
            metadatas,
            documents,
            images,
            uris,
        ) = self._validate_embedding_set(
            ids, embeddings, metadatas, documents, images, uris
        )

        # We need to compute the embeddings if they're not provided
        if embeddings is None:
            # At this point, we know that one of documents or images are provided from the validation above
            if documents is not None:
                embeddings = self._embed(input=documents)
            elif images is not None:
                embeddings = self._embed(input=images)
            else:
                if uris is None:
                    raise ValueError(
                        "You must provide either embeddings, documents, images, or uris."
                    )
                if self._data_loader is None:
                    raise ValueError(
                        "You must set a data loader on the collection if loading from URIs."
                    )
                embeddings = self._embed(self._data_loader(uris))

        return ids, embeddings, metadatas, documents, uris

    def _validate_and_prepare_get_request(
        self,
        ids: Optional[OneOrMany[ID]],
        where: Optional[Where],
        where_document: Optional[WhereDocument],
        include: Include,
    ) -> Tuple[Optional[IDs], Optional[Where], Optional[WhereDocument], Include,]:
        valid_where = validate_where(where) if where else None
        valid_where_document = (
            validate_where_document(where_document) if where_document else None
        )
        valid_ids = validate_ids(maybe_cast_one_to_many_ids(ids)) if ids else None
        valid_include = validate_include(include, allow_distances=False)

        if "data" in include and self._data_loader is None:
            raise ValueError(
                "You must set a data loader on the collection if loading from URIs."
            )

        # We need to include uris in the result from the API to load datas
        if "data" in include and "uris" not in include:
            valid_include.append("uris")  # type: ignore[arg-type]

        return valid_ids, valid_where, valid_where_document, valid_include

    def _transform_peek_response(self, response: GetResult) -> GetResult:
        if response["embeddings"] is not None:
            response["embeddings"] = np.array(response["embeddings"])

        return response

