    )
    .mockImplementationOnce(
      () =>
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        Promise.resolve({ size: 2, results: fakeResponse }) as any
    )
    .mockImplementationOnce(() => Promise.resolve({ size: 0, results: [] }));

