 "id": "2f552f06-c72a-4cf4-a131-c694f4908d67",
 "metadata": {},
 "outputs": [],
 "source": [
  "# to do this, you need to use the langchain object\n",
  "\n",
  "from langchain import hub\n",
  "\n",
  "langchain_prompt = hub.pull(\"rlm/rag-prompt\")"
 ]
},
