How can I limit sourceDocs in langchain + pinecone response in JS? I'm using langchain with pinecode, it gives me 4 sourceDocs but I want only most relevant 1 sourceDoc.
I'm using javascript and don't know where to put top_k in code.
Here's my code
export const makeChain = (vectorStore) => {
  const model = new OpenAI({
    temperature: 0
    modelName: 'gpt-3.5-turbo', 
  });

  const chain = ConversationalRetrievalQAChain.fromLLM(
    model,
    vectorStore.asRetriever(),
    {
      qaTemplate: QA_PROMPT,
      questionGeneratorTemplate: CONDENSE_PROMPT,
      returnSourceDocuments: true,
    }
  );
  return chain;
};

/* create vectorStore*/
